// ---------- v1.89.11: more than one lover — Valentine catches you, the girls settle it in the ring, breakup from chat, harem route ----------
const LOVE_IDS=["kati","mali","rin","ploy","fah"];
const vx=(G,id,M)=>(G.F[id]&&G.F[id].camp==="player"&&M["_"+id])||M[id]; /* "_ploy"/"_fah": once she trains at Sirichai */
const lovList=G=>Array.isArray(G.lovers)?G.lovers:(G.romance?[G.romance]:[]);
const isLov=(G,id)=>!!id&&lovList(G).includes(id);
const isProm=(G,id)=>!!(G.promise&&G.promise[id]!=null);
const isEx=(G,id)=>!!(G.exAbs&&G.exAbs[id]!=null);
const exWait=(G,id)=>isEx(G,id)&&absWeek(G)-G.exAbs[id]<12;
const partners=G=>[...new Set([...lovList(G),...Object.keys(G.promise||{}).filter(k=>G.promise[k]!=null)])].filter(k=>G.F&&G.F[k]);
const isPartner=(G,id)=>partners(G).includes(id);
const romOf=(G,id)=>isLov(G,id)&&!inHm(G,id); // lover-only scenes; on the harem route the top scenes give way to group ones
const romFirst=G=>G.harem&&!hmOut(G).length?null:(lovList(G).find(k=>!inHm(G,k))||null);
function setLovers(G,L){G.lovers=[...new Set(L)];G.romance=G.lovers[0]||null;G.romWk=G.romance?((G.lovWk||{})[G.romance]??null):null;}
function takeLover(G,id){const solo=!partners(G).some(k=>k!==id)&&!rgLovN(G);if(!solo&&G.mono)delete G.mono;if(G.friendz)delete G.friendz[id];G.lovWk=G.lovWk||{};G.lovWk[id]=absWeek(G);if(G.promise)delete G.promise[id];if(G.exAbs)delete G.exAbs[id];setLovers(G,[...lovList(G),id]);if(solo)add(G,id,"morale",15);if(typeof monoSync==="function")monoSync(G);}
const isAway=(G,id)=>{const f=G&&G.F&&G.F[id];return !!(f&&f.awayAbs!=null&&absWeek(G)<f.awayAbs);};
const awayLeft=(G,id)=>isAway(G,id)?G.F[id].awayAbs-absWeek(G):0;
const awaySpeaks=(G,steps)=>(steps||[]).some(x=>x&&typeof x.n==="string"&&isAway(G,x.n));
function sendAway(G,id,wk,why){const f=G.F[id];if(!f)return;const now=absWeek(G);f.awayAbs=Math.max(isAway(G,id)?f.awayAbs:0,now+wk);f.awayWhy=why;f.awayBack=false;}
const lovFinal=G=>{for(const id of lovList(G)){if(!romOf(G,id)||!LOVER_FINAL[id])continue;const b=G.bookings.find(b=>b.tier==="final"&&G.F[b.a].camp==="player"&&(b.a===id||id==="rin"));if(b)return {id,b};}return null;};
/* v1.89.11: one label — the closeness name until you are together, then what you are to each other (shown under the hearts) */
/* v1.91.68 (Man): one rule for every love interest — the five girls and the regional champions.
   She confesses; "not yet" makes you close friends and she asks again later (the girls on a date ≥2 weeks on, the champions every 13 weeks), up to 3 times.
   After the third "no" she steps back for 6 weeks, then reaches out once herself. And you can always tell her yourself (บอกความรู้สึก): not ready yet → 13 weeks before you can try again */
const LOVE_ASK_MAX=3,LOVE_OFF_WK=6,LOVE_TELL_CD=13;
function befriend(G,id){G.friendz=G.friendz||{};G.friendz[id]=true;G.noCnt=G.noCnt||{};G.noCnt[id]=(G.noCnt[id]||0)+1;if(G.noCnt[id]>=LOVE_ASK_MAX){G.loveOff=G.loveOff||{};G.loveOff[id]=absWeek(G);}}
const noCnt=(G,id)=>(G.noCnt&&G.noCnt[id])||0;
const loveOffLeft=(G,id)=>{const a=G.loveOff&&G.loveOff[id];return a==null?0:Math.max(0,LOVE_OFF_WK-(absWeek(G)-a));};
const isFriendz=(G,id)=>!!(G.friendz&&G.friendz[id]);
const awayWord=(G,id)=>G.F[id].camp==="player"?"หนีไปจากค่าย":"ไม่ติดต่อมา";
/* v1.91.72 (Man): a regional champion who has not joined the camp is not a "camp-mate" yet — that rung reads "friend from another camp" for her */
const RG_CHAMP_IDS=["baibua","tabtim","alicia","chaba"];
const outChamp=f=>!!(f&&(RG_CHAMP_IDS.includes(f.id)||f.id==="prod_B"||f.id==="pailin")&&f.camp!=="player"); /* v1.91.122: Baiyok / Pailin too */
const tierFor=(n,f)=>n==="เพื่อนร่วมค่าย"&&outChamp(f)?"เพื่อนต่างค่าย":n;
function relLabel(G,f,lv,short){return tierFor(relLabel0(G,f,lv,short),f);}
function relLabel0(G,f,lv,short){const id=f&&f.id;if(G&&id&&G.F&&G.F[id]&&isAway(G,id)&&G.F[id].awayWhy==="train"){const n=awayLeft(G,id);return short?"ไปฝึกวิชา":`ไปฝึกวิชา (อีก ${n} สัปดาห์)`;}
  if(G&&id&&G.F&&G.F[id]&&isAway(G,id)){const w=G.F[id].awayWhy==="break"?"อกหัก":"งอน";return short?w:`${w} · ${awayWord(G,id)} (อีก ${awayLeft(G,id)} สัปดาห์)`;}
  return relBase(G,f,lv);}
