function runAway(G,id,wk){const f=G.F[id];sendAway(G,id,wk,"cheat");const mine=f.camp==="player";
  return [{n:"nar",bg:"camp",t:mine?`เช้าวันรุ่งขึ้น ${f.name}หายไปจากค่าย ทิ้งไว้แค่โน้ตแผ่นเดียว`:`วันรุ่งขึ้น ${f.name}ส่งข้อความมาสั้น ๆ แล้วก็ไม่ตอบอะไรอีกเลย`},
    {n:"nar",t:`"${RUN_NOTE[id]}"`},{n:"nar",t:mine?`${f.name}ไม่อยู่ค่าย ${wk} สัปดาห์ · ช่วงนี้ซ้อมไม่ได้และรับไฟต์ใหม่ไม่ได้ (ไฟต์ที่จองไว้แล้ว เธอจะกลับมาชก)`:`${f.name}ไม่ติดต่อมา ${wk} สัปดาห์`}];}
function ringSteps(G,a,b,hard){const A=G.F[a].name,B=G.F[b].name;
  return [{fx:()=>{if(typeof UI!=="undefined"&&UI.scene)UI.scene.lookOf={};}},/* into fight gear for the ring */
    {n:"nar",bg:"gym",t:`${A}กับ${B}มองหน้ากันแค่วินาทีเดียว แล้วเดินขึ้นเวทีพร้อมกันโดยไม่มีใครสั่ง`},
    {n:a,f:"angry",l:"fight",t:ringTaunt(G,a,b),with:b},{n:b,f:"angry",l:"fight",t:ringTaunt(G,b,a),with:a},
    {n:"nar",t:"คุณทำได้แค่ยืนข้างเวที แล้วตะโกนห้ามให้ถูกจังหวะ"},
    {brawl:{a,b,hard},after:(G2,res)=>ringAfter(G2,a,b,hard,res||{sc:0})}];}
function ringAfter(G,a,b,hard,res){const A=G.F[a].name,B=G.F[b].name,ok=res.sc>=5,r=[];addU(G,a,b,ok?15:8);addF(G,a,b);
  if(ok)r.push({n:"nar",bg:"gym",t:`${A}กับ${B}ยืนหอบอยู่กลางเวที แล้วจู่ ๆ ก็หัวเราะออกมาพร้อมกัน`},{n:a,f:"pout",l:"fight",t:FIGHT_OK[a],with:b},{n:b,f:"pout",l:"fight",t:FIGHT_OK[b],with:a});
  else r.push({n:"nar",bg:"gym",t:"สุดท้ายครูแดงต้องสาดน้ำเย็นทั้งถังใส่ทั้งคู่ เรื่องถึงได้จบ"},{n:"nar",t:"ทั้งคู่ลงจากเวทีคนละฝั่ง ไม่มีใครหันมามองคุณเลย"});
  if(ok&&!hard)r.push({n:"nar",t:"คืนนั้นไม่มีใครหนีไปไหน แต่ก็ไม่มีใครคุยกับคุณเหมือนกัน"});
  else if(!ok&&hard)r.push(...runAway(G,a,3),...runAway(G,b,3));
  else r.push(...runAway(G,a,hard?3:2));
  return r;}
function valSteps(G){const P=partners(G),hard=(G.valCaught||0)>=1,drop=hard?25:15;G.valCaught=(G.valCaught||0)+1;
  /* the two closest to you settle it in the ring — whichever camp they train at (anyone who already left is not there) */
  const pre=Object.fromEntries(P.map(k=>[k,(G.F[k].bond||0)+(G.F[k].bondX||0)])),byBond=[...P].sort((x,y)=>pre[y]-pre[x]),two=valPair(G,byBond.filter(k=>!isAway(G,k)));
  return [{n:"nar",bg:"camp",t:hard?"วันวาเลนไทน์อีกปี ทุกคนมาหาคุณพร้อมกันอีกแล้ว แต่ปีนี้ไม่มีใครยิ้ม":"14 กุมภาพันธ์ วันวาเลนไทน์ เย็นนั้นคุณนัดไว้… หลายนัด ในเวลาเดียวกัน ที่หน้าค่ายศิริชัย"},
    ...P.map(k=>({n:k,f:hard?"pout":"happy",l:"casual",t:vx(G,k,hard?VAL_AGAIN:VAL_GIFT)})),
    ...(hard?[]:[{n:"nar",t:`${P.map(k=>G.F[k].name).join(" ")} หันมามองหน้ากัน แล้วมองของในมือกันและกัน`},...P.map(k=>({n:k,f:k==="mali"?"sad":"angry",l:"casual",t:VAL_CAUGHT[k]}))]),
    {choice:[{t:"ขอโทษ ฉันผิดเอง",then:[{n:"nar",t:"ไม่มีใครตอบ มีแต่เสียงจิ้งหรีดที่ดังกว่าทุกอย่างในตอนนั้น"}]},
      {t:"ฉันรักทุกคนจริง ๆ ไม่ได้หลอกใครเลย",fx:G2=>{G2.haremOK=true;for(const x of P)for(const y of P)if(x<y)addU(G2,x,y,10);},then:[{n:"nar",t:"ทุกคนเงียบไปนาน… มีบางคนหน้าแดง ทั้งที่ยังโกรธอยู่"}]},
      {t:"ใจเย็นก่อน ฟังฉันอธิบายก่อน",then:[{n:"nar",t:"ยังไม่ทันได้อธิบายสักคำ ถุงขนมก็ลอยมาโดนหน้าคุณ"}]}]},
    {fx:G2=>{P.forEach(k=>add(G2,k,"bond",-drop));G2.pairV=G2.pairV||{};for(const x of P)for(const y of P)if(x<y)G2.pairV[pairKey(x,y)]=(G2.pairV[pairKey(x,y)]||0)+1;G2.valAbs=absWeek(G2);G2.valFloor=Object.fromEntries(P.map(k=>[k,bondTot(G2.F[k])]));}},{n:"nar",t:`ความสนิทกับทุกคนที่คบอยู่ −${drop}`},
    ...(two.length>=2?ringSteps(G,two[0],two[1],hard):[{n:"nar",t:"ไม่มีใครขึ้นเวที แต่ละคนแยกย้ายกลับไปเงียบ ๆ ซึ่งแย่กว่าการทะเลาะกันเสียอีก"},{inject:G2=>runAway(G2,byBond[0],hard?3:2)}])];}
const backDue=(G,id)=>{const f=G.F[id];return !!(f&&f.met&&f.awayAbs!=null&&!f.awayBack&&f.awayWhy!=="train"&&absWeek(G)>=f.awayAbs);}; /* v1.90: the limit-break trip has its own homecoming (region.js) */
