const bondTot=f=>(f.bond||0)+(f.bondX||0);
/* winning them back: a few weeks after Valentine, everyone at lover level again and at least +10 over where the scene left them */
const haremReady=G=>{const P=partners(G),fl=G.valFloor||{};return !!G.haremOK&&hmOut(G).length>0&&P.length>=2&&G.valAbs!=null&&absWeek(G)-G.valAbs>=3&&P.every(k=>bondTot(G.F[k])>=Math.max(75,(fl[k]??0)+10)&&!isAway(G,k));};
function haremForm(G){const P=partners(G);
  return [{n:"nar",bg:"food",t:"คืนหนึ่งหลังวันวาเลนไทน์ผ่านไปหลายสัปดาห์ คุณถูกเรียกไปที่ร้านหมูกระทะหน้าตลาด"},
    {n:"nar",t:`${P.map(k=>G.F[k].name).join(" ")} นั่งรออยู่โต๊ะเดียวกัน ตรงกลางมีกระดาษแผ่นหนึ่งวางอยู่`},
    ...P.map(k=>({n:k,f:"flustered",l:"casual",t:HAREM_YES[k]})),
    {choice:[{t:"ฉันสัญญา จะดูแลทุกคนให้ดีที่สุด",then:[{n:"nar",t:"ทุกคนชนแก้วน้ำแดงพร้อมกัน เสียงดังจนโต๊ะข้าง ๆ หันมามอง"}]},
      {t:"…ทุกคนแน่ใจนะ",then:[{n:"nar",t:"ทุกคนพยักหน้าพร้อมกัน แล้วก็หัวเราะกับความเขินของตัวเอง"}]}]},
    {fx:G2=>{const P2=partners(G2);hmSet(G2,P2);G2.pairSt=G2.pairSt||{};for(const x of P2)for(const y of P2)if(x<y)G2.pairSt[pairKey(x,y)]=3;}},
    {n:"nar",t:"ทุกคนยังเป็นคนรัก ♥ ของคุณ · วันวาเลนไทน์จะไม่มีใครโกรธใครอีก · ฉากหัวใจขั้นสูงสุดของแต่ละคนจะเปลี่ยนเป็นฉากน่ารัก ๆ ของทุกคนแทน"}];}
