function hmSteps(G,S,rot){const P=hmList(G).filter(k=>!isAway(G,k));const out=[{n:"nar",t:S.open}];
  for(const k of P)out.push({n:k,f:"happy",l:"casual",t:vx(G,k,S.say)});
  const B=(S.banter||[]).filter(b=>P.includes(b[0])&&P.includes(b[1]));const o=B.length?(rot??(G.season||1))%B.length:0;
  for(const b of B.slice(o).concat(B.slice(0,o)).slice(0,2))b[2].forEach(([n,t],i)=>out.push({n,f:i%2?"happy":"pout",l:"casual",t,with:n===b[0]?b[1]:b[0]}));
  if(S.react)for(const k of P)out.push({n:k,f:"flustered",l:"casual",t:vx(G,k,S.react)});
  if(S.ask)out.push({n:"nar",t:S.ask.q,choice:S.ask.o.map(x=>({t:x.t,then:[{n:"nar",t:x.r}]}))});
  out.push({n:"nar",t:S.close});
  if(S.react)out.push({fx:G2=>hmList(G2).forEach(k=>add(G2,k,"bond",2))},{n:"nar",t:"ความสนิทกับทุกคน +2"});
  return out;}
