// choices inside these scenes: {t,sc,then} → {t,fx,then} (sc only adds to the date score)
function lvSteps(arr,D,G,id,promise){return arr.map(x=>x.choice?{choice:x.choice.map(o=>({t:o.t,fx:G2=>{if(D)D.score+=o.sc;if(promise){if(G2.mono&&G2.mono.id!==id)delete G2.mono;G2.promise=G2.promise||{};G2.promise[id]=G2.week;add(G2,id,"trust",3);}},then:o.then}))}:x);}
