const CUP_ME={kati:["ขอบคุณค่ะป้า ๆ …ปู่คะ หนูเอาถ้วยกลับบ้านได้แล้วนะ","ป้าคะ หนูกินไม่ทันแล้ว! …แต่หนูจะไม่ปฏิเสธไก่ย่างหรอกนะคะ"],
  mali:["ป้าขา~ มะลิกินหมดทุกปิ่นโตเลยค่ะ! …ขอห่อกลับไปฝากแม่ด้วยได้ไหมคะ","ขนมครกอีกแล้ว~ มะลิรักหมู่บ้านนี้ที่สุดเลย!"],
  rin:["ขอบคุณค่ะ …ฉันไม่ได้คำนวณเผื่อข้าวเหนียวสามกระติกไว้ในแผนเลย","ฉันจะบันทึกไว้ค่ะ ทุกครั้งที่ได้ถ้วย ปิ่นโตเพิ่มขึ้นเฉลี่ยสองเถา"],
  fah:["ป้า ๆ! ฟ้าถ่ายรูปกับถ้วยให้ป้าทุกคนเลย! ยืนเรียงกัน เร็ว ๆ","ไลฟ์เลย! ป้า ๆ โบกมือหน่อย คนดูอยากเห็นแฟนคลับตัวจริงของฟ้า!"],
  ploy:["…ขอบคุณค่ะ สมัยอยู่พยัคฆ์ทอง ไม่เคยมีใครถือปิ่นโตมาหาพลอยแบบนี้เลย","ป้าคะ ไม่ต้องตักให้พลอยเยอะขนาดนั้น …ก็ได้ค่ะ อีกทัพพีเดียว"]};
const CUP_ARRIVE=["ยังไม่ทันแปดโมง ป้า ๆ ในหมู่บ้านก็เดินถือปิ่นโตมายืนเต็มหน้าประตูค่าย",
  "รอบนี้ป้า ๆ มากันเร็วกว่าเดิม บางคนขี่มอเตอร์ไซค์พ่วงข้างมาพร้อมหม้อแกงทั้งหม้อ",
  "หน้าค่ายมีโต๊ะพับมาตั้งรอตั้งแต่ตีหก ไม่มีใครรู้ว่าใครเป็นคนเอามาตั้ง",
  "ถ้วยที่สี่ เสียงประกาศจากหอกระจายข่าวหมู่บ้านดังตั้งแต่ตีห้าครึ่ง ป้า ๆ มากันก่อนนักมวยตื่นเสียอีก"];
const CUP_TAEW=[n=>`${n}! ป้าดูไลฟ์ทั้งคืน ตีกะละมังจนบุบไปใบหนึ่งแล้วลูก! ส้มตำไม่ใส่ปู ไก่ย่าง ข้าวเหนียว กินให้หมดนะ`,
  n=>`${n}! ใบที่แล้วกะละมังบุบ ใบนี้ป้าเปลี่ยนมาตีฝาหม้อแทน …ก็บุบอีกนั่นแหละ`,
  n=>`ป้าตั้งชื่อเมนูใหม่แล้วนะ "ตำ${n}" เผ็ดสามเม็ด เท่ากับจำนวนถ้วยของค่ายเราไง`,
  n=>`${n}… ป้าขายส้มตำหน้าวัดมาสามสิบปี ไม่เคยมีข่าวไหนขายดีเท่าข่าวค่ายนี้เลยลูก`];
const CUP_AUNT=[["ป้าบุญมี ตลาดเช้า",r=>`แชมป์${r}เชียวนะ! สมัยปู่ชัยยังหนุ่ม ป้าเคยเห็นแต่ในทีวี วันนี้มาอยู่หน้าบ้านเราเอง`],
  ["ยายเฉลียว ร้านขนมครก",r=>`ยายทำขนมครกมาสองถาด ถาดหนึ่งให้แชมป์${r} อีกถาดให้คนที่ยังไม่ได้ถ้วย จะได้มีแรง`],
  ["ป้าสมร แม่ค้าผลไม้",r=>`มะม่วงน้ำดอกไม้ลูกที่สวยที่สุดในแผง ป้าเก็บไว้ให้แชมป์${r}คนเดียว คนอื่นห้ามแย่งนะ`],
  ["ป้าจุก ร้านกาแฟโบราณ",r=>`ชาเย็นแก้วนี้ป้าไม่คิดตังค์ แชมป์${r}กินฟรีทั้งปี …แต่มาเล่าเรื่องไฟต์ให้ป้าฟังทุกเช้านะ`]];
const CUP_COACH=["แชมป์ภาคแล้วพรุ่งนี้ก็ตีห้าเหมือนเดิม …แต่เช้านี้ ให้กินก่อน","กินให้อิ่มแล้วไปขอบคุณป้า ๆ ให้ครบทุกคน มวยเราอยู่ได้เพราะคนแถวนี้",
  "ปู่ชัยเคยบอกครูว่า วันไหนป้า ๆ ถือปิ่นโตมาหน้าค่าย วันนั้นค่ายเราเป็นของหมู่บ้านแล้ว","ครบสี่ภาคแล้ว …ครูไม่มีอะไรจะสอนเช้านี้ กินไป"];
const CUP_END=["เช้านั้นทั้งค่ายนั่งกินข้าวกันบนเวทีซ้อม ป้าแต๋วขอยืมถ้วยไปตั้งหน้าร้านส้มตำหนึ่งวัน",
  "ข้าวที่เหลือพอเลี้ยงทั้งค่ายไปอีกสองมื้อ ข้าวตูได้กระดูกไก่ไปหนึ่งถุงใหญ่",
  "ป้า ๆ กลับไปตอนสาย ทิ้งปิ่นโตไว้เต็มโต๊ะ พร้อมกระดาษแผ่นเล็กเขียนว่า \"ล้างแล้วเอามาคืนด้วย\"",
  "ถ้วยทั้งสี่ใบเรียงอยู่บนชั้นเดียวกับรูปปู่ชัย ป้า ๆ ยืนพนมมือไหว้รูปปู่ก่อนกลับ"];
function cupNewsSteps(G,L,me,m){const rn=(typeof RG!=="undefined"&&RG[L.cup]&&RG[L.cup].name)||L.cupName||"ภาค";
  const k=Math.max(0,Math.min(3,((G.region&&G.region.cups||[]).length||1)-1)),A=CUP_AUNT[k],own=CUP_ME[me.id];
  return [
  {n:"nar",t:`เช้าวันต่อมา ข่าว${me.name}คว้าแชมป์${rn}ไปทั่วหมู่บ้าน ตั้งแต่ร้านส้มตำหน้าวัดยันตลาดเช้า`},
  {n:"nar",t:CUP_ARRIVE[k]},
  {n:"npc",who:"ป้าแต๋ว",t:CUP_TAEW[k](me.name)},
  {n:"npc",who:A[0],t:A[1](rn)},
  {n:me.id,f:"happy",l:"casual",t:own?pickR(own,G,"cup_"+me.id):"ขอบคุณค่ะป้า ๆ ทุกคนเลย!"},
  ...(m?[{n:m.id,f:"happy",l:"casual",t:WIN_TEASE[m.id]?pickR(WIN_TEASE[m.id],G,"t_"+m.id)(me.name):`ยินดีด้วยนะ ${me.name}!`}]:[]),
  ...(coachOn()?[{n:"coach",t:CUP_COACH[k]}]:[]),
  {n:"nar",t:CUP_END[k]}];}
function aftermathSteps(G,L){const me=G.F[L.a],op=G.F[L.b];const mates=roster(G).filter(f=>f.id!==me.id);const m=mates[0];if(L.cup)return cupNewsSteps(G,L,me,m);const steps=[];
  if(L.win==="A"){steps.push({n:"nar",t:`เช้าวันต่อมา ข่าว${me.name}เอาชนะ${op.name}ไปทั่วหมู่บ้าน`});
    if(m)steps.push({n:m.id,f:"happy",l:"train",t:WIN_TEASE[m.id]?pickR(WIN_TEASE[m.id],G,"t_"+m.id)(me.name):`ยินดีด้วยนะ ${me.name}!`});
    if(op.id==="ploy")steps.push({n:me.id,f:"flustered",l:"train",t:"หนู… ชนะพี่พลอยได้จริง ๆ เหรอ ตีห้าทุกวันมันไม่เสียเปล่าเลย"});
    else steps.push({n:me.id,f:"happy",l:"train",t:WIN_SELF[me.id]?pickR(WIN_SELF[me.id],G,"s_"+me.id):"แต่ยังไม่พอหรอก!"});
    if(coachOn())steps.push({n:"coach",t:pickR(COACH_WIN,G,"c")});}
  else{if(op.id==="ploy")steps.push({n:"nar",t:"คืนนั้น พลอยเดินลงจากเวทีไปโดยไม่หันกลับมามองเลยสักครั้ง",show:[{id:"ploy",back:true}]});
    steps.push({n:"nar",t:`หลังแพ้${op.name} ${me.name}นั่งเงียบอยู่มุมห้องซ้อมทั้งเช้า`});
    steps.push({n:me.id,f:"sad",l:"train",t:op.id==="ploy"&&me.id==="kati"?"พี่พลอยยังไกลเกินไป… หรือหนูไม่มีทางไปถึงจริง ๆ":LOSS_SELF[me.id]||"…ขอโทษนะ"});
    if(m)steps.push({n:m.id,f:"sad",l:"train",t:m.id==="rin"?`${me.name} ยกสองเธอนำอยู่นะ ฉันมีตัวเลขยืนยัน ไม่ได้แย่อย่างที่คิด`:m.id==="mali"?`${me.name}~ มะลิทำขนมครกไว้ให้แล้ว กินก่อนแล้วค่อยเศร้าต่อนะ`:`${me.name}… ตีห้าพรุ่งนี้ หนูรอซ้อมด้วยนะ`});
    steps.push({choice:[{t:"แพ้ครั้งนี้บอกเราว่าต้องแก้อะไร ไปแก้ด้วยกัน",fx:G=>{add(G,me.id,"morale",6);add(G,me.id,"trust",3);},then:[{n:me.id,f:"happy",l:"train",t:{kati:"…ค่ะ! ครั้งหน้าหนูจะไม่แพ้แบบเดิมอีก",mali:"อื้อ! ครั้งหน้ามะลิเตะให้ถึงทุกลูกเลย!",rin:"ฉันจะทำตารางแก้จุดอ่อนให้เสร็จคืนนี้ค่ะ"}[me.id]||"…ค่ะ!"}]},
      {t:"วันนี้พักก่อน ไปกินอะไรอร่อย ๆ กัน",fx:G=>{add(G,me.id,"bond",4);add(G,me.id,"morale",3);me.fatigue=Math.max(0,me.fatigue-5);},then:[{n:me.id,f:"flustered",l:"casual",t:{kati:"…ขอบคุณนะคะ วันนี้หนูขอแค่นี้ก็พอ",mali:"หมูกระทะได้ไหม~ มะลิหายเศร้าทันทีเลย",rin:"…ไม่มีเหตุผลทางสถิติที่ของอร่อยจะช่วย แต่ฉันจะไปค่ะ"}[me.id]||"…ขอบคุณนะ"}]}]});}
  return steps;}
// v1.16: year-end hooks — beating them is what makes Ploy and Fah look at Sirichai
function season2Hooks(G,key){if(key==="bankrupt")return [];const S=[];
  const beatPloy=G.champ.A==="kati"&&G.finalists.A.includes("ploy"),beatFah=G.champ.B==="mali"&&G.finalists.B.includes("fah");
  if(beatPloy||G.F.ploy.bond>=50){S.push({n:"nar",bg:"camp",t:"สามวันหลังไฟนอล มีคนมายืนหน้าประตูค่ายตั้งแต่ตีห้า ในกางเกงมวยสีม่วงที่ทุกคนจำได้ ราวกับพร้อมจะซ้อมได้ทันที",show:[{id:"ploy",back:true}]},
    ...(beatPloy?[{n:"ploy",f:"sad",l:"casual",t:"ฉันแพ้เป็นครั้งแรกในรอบสามปี… แล้วก็เพิ่งรู้ว่าตลอดเวลาที่ผ่านมา ฉันไม่เคยพยายามจริง ๆ เลย"},
      {n:"ploy",f:"flustered",l:"casual",t:"เถ้าแก่ปลดฉันจากกัปตันแล้ว ค่ายศิริชัย… ยังรับคนที่อยากเริ่มนับหนึ่งใหม่ไหม"}]:
     [{n:"ploy",f:"flustered",l:"casual",t:"ได้ยินว่าค่ายศิริชัยรับสมัครนักมวยปีหน้า… ฉันขอคุยเรื่องสัญญาได้ไหม"}]),
    {choice:[{t:"ประตูค่ายนี้เปิดรอเธออยู่แล้ว",fx:G=>{add(G,"ploy","bond",6);G.s2=Object.assign(G.s2||{},{ploy:"yes"});},then:[{n:"ploy",f:"happy",l:"casual",t:"…ขอบคุณ งั้นพรุ่งนี้ตีห้า ฉันจะมาวิ่งกับกะทิ"}]},
     {t:"คิดให้ดีก่อน ปีหน้าค่อยคุยกันอีกที",fx:G=>{G.s2=Object.assign(G.s2||{},{ploy:"later"});},then:[{n:"ploy",f:"happy",l:"casual",t:"ยุติธรรมดี… ฉันจะกลับมาใหม่"}]}]});}
  if(beatFah||G.F.fah.bond>=50)S.push({n:"fah",f:beatFah?"angry":"happy",l:"casual",t:beatFah?"เด็กไชยานั่นเตะฟ้าจนหูอื้อเลยนะ! …ปีหน้าฟ้าขอมาซ้อมที่นี่ ไม่งั้นแก้มือไม่ได้สักที":"เฮ้ ปีหน้าฟ้าขอย้ายมาค่ายนายได้ไหม! ที่พยัคฆ์ทองมันน่าเบื่อแล้ว"});
  if(S.length)S.push({n:"nar",t:"ปีหน้า ค่ายศิริชัยอาจมีนักมวยมากกว่าที่ใครคิด…"});
  return S;}
