const POACH_WHY={mali:"เถ้าแก่บอกว่าจะให้เงินเดือนสองเท่า… หนูจะส่งเงินให้แม่ได้เยอะขึ้นมาก",rin:"เถ้าแก่บอกว่าคราวนี้จะฟังข้อมูลของฉัน ให้ห้องวิเคราะห์เป็นของตัวเอง… ซึ่งที่นั่นไม่เคยมี"};
