function vectorFightScene(G,b){const op=G.F[b.b];if((G.season||1)<4||!op||!op.lab)return null;G.seenY=G.seenY||{};
  const key="vector_face_"+op.id,first=G.seenY[key]!==G.season;G.seenY[key]=G.season;const y=G.season||1,late=y>=6;
  if(op.id==="pailin")return [{n:"nar",t:first?(late?`ปีที่ ${y} ไพลินขึ้นเวทีในชุดดำม่วงตัวใหม่ เสียงคนดูดังขึ้นทันทีเพราะทุกคนรู้ว่าศึกนี้คือศึกประจำปี`:"ไพลินขึ้นเวทีในชุดดำม่วง เธอไม่มองจอวิเคราะห์เลย สายตาจ้องตรงมาที่มุมค่ายศิริชัย"):"ไพลินกลับมาท้าค่ายศิริชัยอีกครั้งในปีเดียวกัน รอยยิ้มดุ ๆ ยังเหมือนเดิม"},
    {n:"pailin",f:"angry",l:"fight",t:b.a==="ploy"?(first?(late?"พลอย ปีนี้พี่ไม่ออมมือให้เหมือนเดิม ขึ้นมา!":"พลอย อย่าหลบอยู่หลังชื่อค่าย แสดงมวยของเธอให้พี่เห็น!"):"คราวก่อนยังไม่พอ พี่อยากเห็นเธอชกอีก"):(first?(late?`ปีที่ ${y} แล้ว เธอยังไม่เบื่อแพ้ฉันอีกเหรอ …ล้อเล่น มาเลย!`:"ข้อมูลบอกว่าฉันชนะ แต่ฉันอยากเห็นด้วยตาตัวเอง"):"ไฟต์ที่แล้วฉันจดทุกจังหวะไว้แล้ว ขึ้นมา!")},
    {n:b.a,f:"angry",l:"fight",t:b.a==="ploy"?"ฉันจะชกในชื่อของฉัน พี่ดูให้ดี":"ค่ายศิริชัยพร้อมแล้วค่ะ"}];
  return [{n:"nar",t:first?`นักมวยค่ายเวกเตอร์ในชุดดำม่วงขึ้นเวที จอด้านหลังแสดงกราฟการเคลื่อนไหวของ${G.F[b.a].name}`:`${op.name}กลับมาเจอศิริชัยอีกครั้ง คราวนี้จอวิเคราะห์ดับลงก่อนระฆัง`},
    {n:"npc",who:op.name,t:op.id==="vector_A"?(first?"ฉันดูเทปเธอมาทุกยก แต่จะตัดสินใจเองเมื่อขึ้นเวที":"คราวนี้ฉันจะอ่านเธอด้วยตา ไม่ใช่แค่กราฟ"):(first?"เครื่องบอกให้ฉันพักเมื่อวาน ฉันพักแล้ว วันนี้พร้อมชก":"ข้อมูลช่วยได้ แต่คำตอบสุดท้ายอยู่ในนวม")},
    {n:b.a,f:"angry",l:"fight",t:"งั้นมาวัดกันบนเวที"}];}
function vectorResultScene(G,b,win){const op=G.F[b.b];if((G.season||1)<4||!op||!op.lab)return null;G.seenY=G.seenY||{};
  G.vecRec=G.vecRec||{};const R=G.vecRec[G.season]=G.vecRec[G.season]||{w:0,l:0};if(win==="A")R.w++;else if(win==="B")R.l++;
  const key="vector_result_"+op.id;if(G.seenY[key]===G.season)return null;G.seenY[key]=G.season;
  if(op.id==="pailin")return [{n:"nar",t:"เสียงระฆังจบ ไพลินถอดนวมข้างหนึ่ง แล้วเดินข้ามเวทีมาหาคู่ชกด้วยตัวเอง"},
    {n:"pailin",f:win==="A"?"surprised":"happy",l:"fight",t:b.a==="ploy"?(win==="A"?"พลอย… เธอชนะพี่ด้วยมวยของตัวเองจริง ๆ":"แพ้วันนี้ไม่ใช่จุดจบของเธอ กลับมาชกกับพี่อีกนะ"):(win==="A"?"ดี! วันนี้ฉันแพ้ แต่ปีหน้าฉันจะแกร่งกว่าเดิม":"อย่าหยุดซ้อมล่ะ ฉันอยากเจอเธอที่เก่งกว่านี้")},
    {inject:G=>b.a==="ploy"?[{n:"ploy",f:"happy",l:"fight",t:"ปีหน้าเจอกันใหม่ค่ะพี่ คราวนี้คุยกันหลังลงเวทีด้วยนะ"}]:[{n:b.a,f:"happy",l:"fight",t:"รับคำท้าค่ะ ปีหน้าเจอกัน"}]}];
  return [{n:"nar",t:"หลังไฟต์ นักมวยเวกเตอร์ถอดสายวัดชีพจรออกเอง แล้วเดินมาชนนวมกับนักมวยศิริชัย"},
    {n:"npc",who:op.name,t:win==="A"?"วันนี้เธออ่านฉันออก ข้อมูลชุดใหม่ต้องเริ่มจากไฟต์นี้":"วันนี้ฉันชนะ แต่ไฟต์หน้าฉันไม่คิดว่าเธอจะชกแบบเดิม"},
    {n:b.a,f:"happy",l:"fight",t:"ไว้เจอกันอีก ชกให้เต็มที่เหมือนเดิมนะ"}];}

