  const optHalf=G=>({t:`ต่อรอง และให้${D.cul(G)}ช่วยทำงานใช้หนี้ (จ่ายครึ่งเดียว)`,fx:G2=>{G2._drain=drainPay(G2,.5);},
    then:[{inject:G2=>[{n:"nar",t:`จ่ายไป ${fmt(G2._drain)} · ${D.cul(G2)}ไปช่วยงานจนครบ แต่ก็บ่นทั้งสัปดาห์`}]}]});
